"""
Canonical definition of what counts as a produced artifact.

This module centralizes the logic for filtering out machine-generated directories
and malformed paths (e.g., those containing markdown artifacts) from agent
workspace bundles. This ensures consistent counting of authored files across
the runtime, verifier, and analysis scripts.
"""

from typing import Dict, Tuple, Iterable

# Directories that are typically generated by tools or environments and should
# not be counted as agent-authored artifacts.
EXCLUDED_DIR_SEGMENTS = (
    '.pytest_cache',
    '__pycache__',
    'venv',
    '.venv',
    '.git',
    '.mypy_cache',
    '.ruff_cache',
    '.tox',
    'node_modules',
    '.ipynb_checkpoints'
)

# Directory suffixes that indicate package metadata or build artifacts.
EXCLUDED_DIR_SUFFIXES = (
    '.egg-info',
    '.dist-info'
)


def is_generated_path(path: str) -> bool:
    """
    True if the path lives inside a machine-generated directory.
    
    Checks if any segment of the path matches EXCLUDED_DIR_SEGMENTS or if any
    directory component ends with a suffix in EXCLUDED_DIR_SUFFIXES.
    """
    if not path:
        return False
    
    # Normalize separators to forward slash for consistent splitting
    normalized_path = path.replace('\\', '/')
    segments = normalized_path.split('/')
    
    for segment in segments:
        if not segment:
            continue
        
        # Check against exact segment matches
        if segment in EXCLUDED_DIR_SEGMENTS:
            return True
        
        # Check against suffix matches for directory-like segments
        # We check all segments except potentially the last one if it's a file,
        # but usually these suffixes appear in directory names like 'pkg.egg-info'.
        # If the segment itself ends with the suffix, it's likely a generated dir.
        for suffix in EXCLUDED_DIR_SUFFIXES:
            if segment.endswith(suffix):
                return True
                
    return False


def is_malformed_path(path: str) -> bool:
    """
    True if markdown formatting, stray whitespace, or invalid punctuation leaked into the filename.

    Agents emit paths through a ReAct text protocol, so bold markers (`*`),
    backticks (`` ` ``), leading/trailing whitespace, trailing dots (`.`) or
    tildes (`~`), or leading hyphens (`-`) periodically survive into `write_file`
    calls. The resulting files are unusable -- `routing.py**` or `notes.` is not
    valid -- so any path containing `*` or `` ` ``, leading/trailing whitespace,
    starting with `-`, or ending with `.` or `~` is malformed.
    """
    if not path:
        return False
    
    # Check for markdown characters
    if '*' in path or '`' in path:
        return True
        
    # Check for leading/trailing whitespace
    if path != path.strip():
        return True
        
    # Check for leading hyphen
    if path.startswith('-'):
        return True
        
    # Check for trailing dot or tilde
    if path.endswith('.') or path.endswith('~'):
        return True
        
    return False


def sanitize_path(path: str) -> str:
    """
    Strips markdown decoration from an agent-supplied path.

    Applied at write time so the artifact lands at its intended location rather
    than being silently created with a broken name.
    """
    if not path:
        return path
        
    # Strip leading/trailing whitespace
    sanitized = path.strip()
    
    # Remove markdown bold/italic markers and backticks
    # We remove them entirely as they are decoration, not part of the filename
    sanitized = sanitized.replace('*', '')
    sanitized = sanitized.replace('`', '')
    
    # Handle leading hyphens? The spec says sanitize strips markdown decoration.
    # Leading hyphens are considered malformed but not necessarily "markdown decoration"
    # in the same way * and ` are. However, often `-` at start might be accidental.
    # The spec for is_malformed says starting with '-' is malformed.
    # The spec for sanitize says "Strips markdown decoration".
    # Usually, sanitization implies making it valid. 
    # If we just strip * and ` and whitespace, we might still have a leading hyphen.
    # Let's look at the examples: `routing.py**` -> `routing.py`. `notes.` -> `notes`?
    # The docstring for is_malformed says `notes.` is not valid.
    # If sanitize is meant to fix it, it should probably remove trailing dots too?
    # "Strips markdown decoration" is specific. 
    # Let's stick to removing the explicit markdown chars (*, `) and whitespace.
    # If the path starts with '-', it's malformed but maybe not "markdown decoration".
    # However, often agents might output "- file.py". 
    # Let's assume sanitize removes the obvious markdown noise.
    
    # Re-evaluating based on "Applied at write time so the artifact lands at its intended location"
    # If the agent meant `routing.py` but wrote `**routing.py**`, sanitize should yield `routing.py`.
    # If the agent meant `notes.txt` but wrote `notes.txt.`, sanitize should probably yield `notes.txt`.
    # But the docstring specifically says "Strips markdown decoration".
    # Let's implement removal of *, `, and whitespace.
    
    return sanitized


def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """
    Returns only genuinely agent-authored files from a path->content map.
    
    Filters out paths that are generated or malformed.
    """
    filtered = {}
    for path, content in bundle.items():
        if not is_generated_path(path) and not is_malformed_path(path):
            filtered[path] = content
    return filtered


def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
    """
    Splits a bundle into (authored, generated, malformed) for reporting.
    
    Returns:
        Tuple of three dicts:
        1. Authored: Files that are neither generated nor malformed.
        2. Generated: Files that are in generated directories.
        3. Malformed: Files that have malformed paths (and are not generated).
        
    Note: If a path is both generated and malformed, it is classified as generated
    because the directory structure is the primary reason for exclusion.
    """
    authored = {}
    generated = {}
    malformed = {}
    
    for path, content in bundle.items():
        if is_generated_path(path):
            generated[path] = content
        elif is_malformed_path(path):
            malformed[path] = content
        else:
            authored[path] = content
            
    return authored, generated, malformed


def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
    """
    Counts authored files matching the given suffixes.
    
    First filters the bundle to remove generated and malformed paths,
    then counts the remaining files that end with any of the provided suffixes.
    """
    authored_files = filter_bundle(bundle)
    count = 0
    for path in authored_files.keys():
        if any(path.endswith(suffix) for suffix in suffixes):
            count += 1
    return count